4384: /* ===================== LVGL 打桩（一次性挂在 display 上） =====================
4385:  * 用户 2026-09-26："对 lvgl 怎么各种打桩验证吧"。这一套覆盖四件事，全部
4386:  * **只在有活动时每 5 秒汇总一行**（不逐帧打，免得把日志刷满）：
4387:  *
4388:  *   [vperf] ui 5s renders=42 slow=7 render=310ms flush=180ms
4389:  *                 | fill_sq=96 fill_round=58 label=210 img=4 other=12
4390:  *
4391:  *  · renders/slow/render  —— 每帧渲染耗时（含慢帧数）。慢帧多 ⇒ 绘制本身贵。
4392:  *  · flush               —— **屏刷写的耗时**（LCDC/DMA 那一段）。它大而 render 小
4393:  *                           ⇒ 卡在屏，不在绘制，该去查帧缓存内存与总线。
4394:  *  · fill_sq / fill_round —— 填充任务按"方角 / 圆角"分开数。这条最值钱：
4395:  *                            lv_draw_sifli_epic.c 里 radius != 0 会被 EPIC **拒绝**
4396:  *                            （原文 "EPIC doesn't support rounded corners"），
4397:  *                            所以 fill_round 就是"被踢回 CPU 光栅化"的量；
4398:  *                            这个数一涨、render 跟着涨，就是 GPU 没吃上。
4399:  *  · label/img/other      —— 文字/图片任务数（EPIC 有 label 与 img 通道）。
4400:  *
4401:  * 另外开机打一行帧缓存身份（在哪块内存、多大），见 helm_lvgl_probe_attach。
4402:  * 判读地址：0x2000_xxxx 片上 SRAM（非缓存但快）；0x6000_xxxx PSRAM SBUS
4403:  * （**write-through**，写惩罚实测 ~10 MB/s）；0x1000_xxxx PSRAM CBUS（可缓存）。
4404:  */
4405: typedef struct {
4406:     uint32_t renders;
4407:     uint32_t slow;
4408:     uint32_t render_ms;
4409:     uint32_t flush_ms;
4410:     uint32_t fill_sq;
4411:     uint32_t fill_round;
4412:     uint32_t label;
4413:     uint32_t img;
4414:     uint32_t other;
4415:     uint32_t t_render;
4416:     uint32_t t_flush;
4417:     uint32_t t_window;
4418: } helm_lvgl_probe_t;
