4420: static helm_lvgl_probe_t s_probe;
4421: 
4422: void helm_ui_task_cb(lv_event_t * e)
4423: {
4424:     lv_draw_task_t * t = (lv_draw_task_t *)lv_event_get_param(e);
4425: 
4426:     if (t == NULL) {
4427:         return;
4428:     }
4429: 
4430:     switch (t->type) {
4431:     case LV_DRAW_TASK_TYPE_FILL:
4432:         {
4433:             const lv_draw_fill_dsc_t * d = (const lv_draw_fill_dsc_t *)t->draw_dsc;
4434: 
4435:             if (d != NULL && d->radius != 0) {
4436:                 s_probe.fill_round++;     /* EPIC 不吃 ⇒ 落 CPU */
4437:             } else {
4438:                 s_probe.fill_sq++;        /* 方角 ⇒ 能走 GPU */
4439:             }
4440:         }
4441:         break;
4442: 
4443:     case LV_DRAW_TASK_TYPE_LABEL:
4444:         s_probe.label++;
4445:         break;
4446: 
4447:     case LV_DRAW_TASK_TYPE_IMAGE:
4448:         s_probe.img++;
4449:         break;
4450: 
4451:     default:
4452:         s_probe.other++;
4453:         break;
4454:     }
4455: }
