4457: static void helm_lvgl_probe_cb(lv_event_t * e)
4458: {
4459:     switch (lv_event_get_code(e)) {
4460:     case LV_EVENT_RENDER_START:
4461:         s_probe.t_render = lv_tick_get();
4462:         break;
4463: 
4464:     case LV_EVENT_RENDER_READY:
4465:         {
4466:             uint32_t ms = lv_tick_elaps(s_probe.t_render);
4467: 
4468:             s_probe.renders++;
4469:             s_probe.render_ms += ms;
4470:             if (ms >= HELM_UI_SLOW_MS) {
4471:                 s_probe.slow++;
4472:             }
4473:         }
4474:         break;
4475: 
4476:     case LV_EVENT_FLUSH_START:
4477:         s_probe.t_flush = lv_tick_get();
4478:         break;
4479: 
4480:     case LV_EVENT_FLUSH_FINISH:
4481:         s_probe.flush_ms += lv_tick_elaps(s_probe.t_flush);
4482:         break;
4483: 
4484:     default:
4485:         break;
4486:     }
4487: }
